import {initialProducts,initialOrders,initialCustomers,initialCoupons,initialContacts,initialArticles} from './data.js';
const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',cart:'<path d="M2 3h3l3 13h11l3-9H6M9 21h.01M18 21h.01"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 11 3 3 5-5"/>',truck:'<path d="M2 5h12v13H2zM14 10h5l3 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',support:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12H2v7h4v-7zm16 0h2v7h-4v-7zM20 19v3h-8"/>',box:'<path d="m12 2 10 5-10 5L2 7zM2 7v11l10 5 10-5V7M12 12v11M7 4l10 5"/>',grid:'<path d="M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z"/>',orders:'<path d="M6 3h12v19l-3-2-3 2-3-2-3 2zM9 8h6M9 12h6M9 16h4"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V7m5 9v-6"/>',tag:'<path d="M3 3h8l11 11-8 8L3 11z"/><circle cx="7" cy="7" r="1"/>',news:'<path d="M4 3h16v18H4zM8 7h8M8 11h8M8 15h3M14 15h2M8 18h8"/>',mail:'<path d="M2 5h20v14H2zM2 5l10 8L22 5"/>',exit:'<path d="M9 3H3v18h6m4-9h9m-4-4 4 4-4 4"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7l-5-5L3 15z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 16h12l1-16M10 10v8m4-8v8"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',calendar:'<path d="M3 5h18v16H3zM3 10h18M7 2v6M17 2v6"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',lock:'<path d="M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',building:'<path d="M4 22V3h12v19M16 11h5v11M2 22h21M8 7h4M8 11h4M8 15h4M8 19h4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('vi-VN').format(v)+'₫';
const key='campro-interface-v1';
const seed=()=>({products:structuredClone(initialProducts),orders:structuredClone(initialOrders),customers:structuredClone(initialCustomers),coupons:structuredClone(initialCoupons),contacts:structuredClone(initialContacts),articles:structuredClone(initialArticles),categories:[{id:1,name:'Trong nhà',description:'Camera cho không gian trong nhà',active:true},{id:2,name:'Ngoài trời',description:'Camera cho sân, cổng và cửa hàng',active:true},{id:3,name:'Dùng pin',description:'Camera lắp đặt linh hoạt',active:true}],suppliers:[{id:1,name:'TP-Link Tapo',email:'supplier@example.com',phone:'0900000010',description:'Camera thông minh Wi-Fi',active:true}],cart:[],session:null,compare:[]});
let db;try{db=JSON.parse(localStorage.getItem(key))||seed()}catch{db=seed()}
let saveChain=Promise.resolve(),apiOnline=false;
async function api(path,options={}){const response=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||body.detail||'Không thể xử lý yêu cầu.');return body}
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('Trình duyệt không lưu được dữ liệu.')}if(apiOnline){saveChain=saveChain.then(()=>api('/state/sync',{method:'POST',body:JSON.stringify(db)})).catch(error=>{console.error(error);toast('Chưa thể lưu vào MySQL. Hãy kiểm tra XAMPP.')})}}
async function hydrate(){const local=db;try{const server=await api('/state');db={...server,cart:server.session?server.cart:(local.cart||[]),compare:local.compare||[]};apiOnline=true;localStorage.setItem(key,JSON.stringify(db))}catch(error){console.error(error);toast('Đang dùng dữ liệu cục bộ vì chưa kết nối được MySQL.')}handleRoute()}
let coupon='',catalog={q:'',cats:[],resolution:[],price:'',sort:'featured'},adminSearch='',adminStatus='',reportFrom='2026-09-01',reportTo='2026-09-30',homeCategory='Tất cả';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let returnAfterLogin='';
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500)}
function go(path){if(location.hash==='#'+path){render();window.scrollTo(0,0)}else location.hash=path}
const route=()=>decodeURI(location.hash.slice(1)||'/');
const product=id=>db.products.find(p=>p.id===Number(id));
const cartItems=()=>db.cart.map(c=>({...product(c.id),quantity:c.quantity})).filter(p=>p.id&&p.active);
const subtotal=()=>cartItems().reduce((s,p)=>s+p.price*p.quantity,0);
function discountFor(code,total){const c=db.coupons.find(c=>c.code===code.toUpperCase()&&c.active);if(!c)return{amount:0,error:'Mã không tồn tại hoặc đã ngừng áp dụng.'};if(total<c.min)return{amount:0,error:'Đơn hàng tối thiểu '+money(c.min)+' để dùng mã này.'};return{amount:Math.min(total,c.type==='percent'?Math.min(total*c.value/100,c.max||Infinity):c.value),error:''}}
const logo=()=>`<a href="#/" class="logoblock brandlogo" aria-label="CAMPRO — Trang chủ"><img src="./assets/campro-logo.svg" alt="CAMPRO — Camera & Security"><span class="brandfallback"><span class="logo">CAM<b>PRO</b></span><small>CAMERA & SECURITY</small></span></a>`;
const badge=s=>`<span class="badge ${s==='Hoàn thành'||s==='Đã giao'||s==='Đã phản hồi'?'success':s==='Đã hủy'?'neutral':s==='Đang giao'||s==='Đã xác nhận'?'blue':''}">${esc(s)}</span>`;
const crumb=(title,parent='')=>`<div class="breadcrumb"><a href="#/">Trang chủ</a>${icon('chevron')}${parent?`<a href="#/san-pham">Sản phẩm</a>${icon('chevron')}`:''}<span>${esc(title)}</span></div>`;
const title=(h,p='')=>`<div class="pagetitle"><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const empty=(h,p,link='/san-pham',label='Khám phá sản phẩm')=>`<div class="empty">${icon('box')}<h3>${h}</h3><p>${p}</p><a class="btn" href="#${link}">${label}${icon('arrow')}</a></div>`;
function header(){return `<div class="previewrail"><div class="wrap"><span>CAMPRO · CAMERA & GIẢI PHÁP AN NINH</span><a href="#/admin">Trang quản trị ↗</a></div></div><div class="topbar"><div class="wrap"><div><span>Thiết bị chính hãng</span><span>Tư vấn đúng nhu cầu</span></div><div class="right">An tâm từ những điều nhỏ nhất.</div></div></div><header><div class="wrap mainhead">${logo()}<form class="searchbox" id="search-form" role="search"><input name="q" placeholder="Bạn đang tìm camera cho đâu?" value="${esc(catalog.q)}" aria-label="Tìm kiếm camera"><button aria-label="Tìm kiếm">${icon('search')}</button></form><div class="head-actions"><a href="#/don-hang" aria-label="Đơn hàng của tôi">${icon('orders')}<span>Tra cứu<b>Đơn hàng</b></span></a><a href="#/tai-khoan" aria-label="Tài khoản">${icon('user')}<span>Xin chào,<b>${db.session?esc(db.session.name.split(' ').slice(-2).join(' ')):'Đăng nhập'}</b></span></a><a href="#/gio-hang" aria-label="Giỏ hàng"><span class="cart-icon">${icon('cart')}<b class="count">${db.cart.reduce((s,c)=>s+c.quantity,0)}</b></span><span>Giỏ hàng<b>${money(subtotal())}</b></span></a></div></div><div class="navborder"><nav class="wrap shopnav"><a class="allcat" href="#/san-pham">${icon('menu')} Tất cả sản phẩm</a><a href="#/san-pham?category=Trong%20nhà">Camera trong nhà</a><a href="#/san-pham?category=Ngoài%20trời">Camera ngoài trời</a><a href="#/san-pham?category=Dùng%20pin">Camera dùng pin</a><a href="#/tin-tuc">Góc tư vấn</a><a href="#/lien-he">Liên hệ</a><span class="navend">Tư vấn lắp đặt theo nhu cầu</span></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footergrid"><div>${logo()}<p>Camera phù hợp. Quan sát rõ ràng.<br>An tâm trong từng không gian sống.</p></div><div><h4>KHÁM PHÁ</h4><a href="#/san-pham">Tất cả camera</a><a href="#/san-pham?category=Trong%20nhà">Camera trong nhà</a><a href="#/san-pham?category=Ngoài%20trời">Camera ngoài trời</a><a href="#/tin-tuc">Kiến thức camera</a></div><div><h4>HỖ TRỢ KHÁCH HÀNG</h4><a href="#/don-hang">Theo dõi đơn hàng</a><a href="#/chinh-sach">Giao hàng & thanh toán</a><a href="#/chinh-sach">Bảo hành & đổi trả</a><a href="#/lien-he">Liên hệ tư vấn</a></div><div><h4>KẾT NỐI VỚI CAMPRO</h4><p>Hỗ trợ lựa chọn thiết bị và giải pháp cho gia đình, cửa hàng.</p><a href="#/lien-he" style="color:var(--ink);margin-top:15px">Gửi yêu cầu tư vấn ↗</a></div></div><div class="footerline"><span>© 2026 CAMPRO. Camera & Giải pháp an ninh.</span><span>Dữ liệu cửa hàng được quản lý bằng ASP.NET Core và MySQL</span></div></div></footer>`}
function card(p){return `<article class="productcard"><a href="#/san-pham/${p.id}" class="productphoto"><span class="tag">${esc(p.tag||'CAMERA CHÍNH HÃNG')}</span><img src="./assets/${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" width="240" height="240"></a><div class="productbody"><div class="productbrand">${esc(p.brand)}</div><h3><a href="#/san-pham/${p.id}">${esc(p.name)}</a></h3><p>${esc(p.subtitle)}</p><div class="specchips"><span>${esc(p.resolution)}</span><span>${esc(p.angle)}</span><span>${esc(p.connection)}</span></div><div class="prices"><strong class="price">${money(p.price)}</strong>${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</div><div class="productbottom"><span class="stock ${p.stock?'':'out'}">${p.stock?'Sẵn hàng':'Tạm hết hàng'}</span><button class="iconbtn" data-add="${p.id}" aria-label="Thêm ${esc(p.name)} vào giỏ" ${p.stock?'':'disabled'}>${icon('plus')}</button></div></div><label class="comparecheck"><input type="checkbox" data-compare="${p.id}" ${db.compare.includes(p.id)?'checked':''}> So sánh sản phẩm</label></article>`}
function compareBar(){return db.compare.length?`<div class="comparebar"><div><b>${db.compare.length}/3 sản phẩm</b><small> · ${db.compare.map(id=>esc(product(id)?.name)).join(' / ')}</small></div><div class="flex"><button class="textbtn" data-action="clear-compare">Bỏ chọn</button><a class="btn smallbtn" href="#/so-sanh">So sánh ${icon('arrow')}</a></div></div>`:''}
function home(){const ps=db.products.filter(p=>p.active&&(homeCategory==='Tất cả'||p.category===homeCategory)).slice(0,4);return `<div class="wrap"><section class="homehero"><div class="herotext"><div class="eyebrow">QUAN SÁT RÕ HƠN. AN TÂM NHIỀU HƠN.</div><h1>An tâm ở nhà.<br>Dù bạn ở đâu.</h1><p>Camera thông minh cho gia đình và cửa hàng. Chọn đúng thiết bị, bảo vệ điều quan trọng.</p><div class="heroactions"><a class="btn redbtn" href="#/san-pham">Khám phá camera ${icon('arrow')}</a><a class="textbtn" href="#/lien-he">Tư vấn chọn mua</a></div><div class="herofoot"><span>${icon('check')} Thiết bị chính hãng</span><span>${icon('check')} Hỗ trợ cài đặt</span></div></div><div class="herovisual"><span class="hero-type">C225</span><img src="./assets/c225.jpg" alt="Camera TP-Link Tapo C225" width="400" height="400" fetchpriority="high"><span class="hero-feature">2K QHD<br><b>Chi tiết trong từng góc nhìn</b></span><a href="#/san-pham/1" class="hero-label">TP-LINK TAPO C225<strong>990.000₫ <span style="font-size:14px;margin-left:15px">↗</span></strong></a></div></section><div class="benefits">${[['shield','Nguồn gốc rõ ràng','Thông tin thiết bị minh bạch'],['truck','Giao hàng toàn quốc','Theo dõi đơn hàng dễ dàng'],['support','Tư vấn đúng nhu cầu','Hỗ trợ trước và sau mua'],['box','Chính sách rõ ràng','An tâm khi chọn thiết bị']].map(([i,t,s])=>`<div class="benefit">${icon(i)}<div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div><section class="section"><div class="sectionhead"><div><div class="eyebrow">BẠN MUỐN QUAN SÁT Ở ĐÂU?</div><h2>Chọn theo không gian</h2></div><a href="#/san-pham">Tất cả sản phẩm ${icon('arrow')}</a></div><div class="categories">${[['Trong nhà','Gia đình, phòng khách','c200.jpg'],['Ngoài trời','Sân, cổng, cửa hàng','c320ws.png'],['Dùng pin','Linh hoạt vị trí lắp','c425.jpg'],['Tất cả','Khám phá mọi lựa chọn','c520ws.jpg']].map(([c,s,img])=>`<a class="category" href="#/san-pham${c==='Tất cả'?'':'?category='+encodeURIComponent(c)}"><div><strong>${c==='Tất cả'?'Mọi không gian':c}</strong><small>${s} ↗</small></div><img src="./assets/${img}" alt="" width="66" height="69"></a>`).join('')}</div></section><section class="section" style="padding-top:6px"><div class="sectionhead"><div><div class="eyebrow">THIẾT BỊ CHO CUỘC SỐNG AN TÂM</div><h2>Camera đáng tham khảo</h2></div><a href="#/san-pham">Xem bộ sưu tập ${icon('arrow')}</a></div><div class="tabs">${['Tất cả','Trong nhà','Ngoài trời','Dùng pin'].map(c=>`<button data-homecat="${c}" class="${homeCategory===c?'active':''}">${c}</button>`).join('')}</div><div class="productgrid">${ps.map(card).join('')}</div></section><div class="consultbanner"><div><div class="eyebrow" style="color:#b7c1af;margin-bottom:7px">MỖI KHÔNG GIAN, MỘT GIẢI PHÁP</div><h2>Chưa biết nên chọn camera nào?</h2><p>Cho chúng tôi biết nhu cầu. Cùng tìm thiết bị phù hợp với bạn.</p></div><a class="btn" href="#/lien-he">Nhận tư vấn ${icon('arrow')}</a></div><div class="brands"><small>CÔNG NGHỆ<br>BẠN TIN TƯỞNG</small><strong>tapo</strong><strong style="font-style:italic">HIKVISION</strong><strong style="font-style:italic">dahua</strong><strong>EZVIZ</strong><strong>imou</strong></div><section class="section"><div class="sectionhead"><div><div class="eyebrow">HIỂU THIẾT BỊ, CHỌN ĐÚNG NHU CẦU</div><h2>Góc tư vấn camera</h2></div><a href="#/tin-tuc">Tất cả bài viết ${icon('arrow')}</a></div>${articlesGrid()}</section></div>`}
function filteredProducts(){let ps=db.products.filter(p=>p.active&&p.name.toLowerCase().includes(catalog.q.toLowerCase())&&(!catalog.cats.length||catalog.cats.includes(p.category))&&(!catalog.resolution.length||catalog.resolution.includes(p.resolution)));if(catalog.price==='under')ps=ps.filter(p=>p.price<1000000);if(catalog.price==='mid')ps=ps.filter(p=>p.price>=1000000&&p.price<=2000000);if(catalog.price==='over')ps=ps.filter(p=>p.price>2000000);if(catalog.sort==='asc')ps.sort((a,b)=>a.price-b.price);if(catalog.sort==='desc')ps.sort((a,b)=>b.price-a.price);if(catalog.sort==='name')ps.sort((a,b)=>a.name.localeCompare(b.name));return ps}
function catalogPage(){const ps=filteredProducts();return `<div class="wrap">${crumb('Camera giám sát')}${title('Camera giám sát','Tìm chiếc camera phù hợp với không gian và ngân sách của bạn.')}<div class="cataloglayout"><aside class="filters" id="filters"><div class="filtergroup between"><h3 style="margin:0">Bộ lọc sản phẩm</h3><button class="textbtn small" data-action="reset-filter">Xóa lọc</button></div><div class="filtergroup"><h3>Vị trí lắp đặt</h3>${db.categories.filter(c=>c.active).map(c=>`<label><input type="checkbox" data-filter="cats" value="${esc(c.name)}" ${catalog.cats.includes(c.name)?'checked':''}>${esc(c.name)}<span>${db.products.filter(p=>p.active&&p.category===c.name).length}</span></label>`).join('')}</div><div class="filtergroup"><h3>Khoảng giá</h3><select aria-label="Lọc theo khoảng giá" data-filter="price">${[['','Tất cả mức giá'],['under','Dưới 1 triệu'],['mid','1 – 2 triệu'],['over','Trên 2 triệu']].map(([v,t])=>`<option value="${v}" ${catalog.price===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="filtergroup"><h3>Độ phân giải</h3>${['Full HD','2K QHD','4K'].map(r=>`<label><input type="checkbox" data-filter="resolution" value="${r}" ${catalog.resolution.includes(r)?'checked':''}>${r}</label>`).join('')}</div><div class="filtergroup"><h3>Cần tư vấn thêm?</h3><p class="small muted">Chọn camera theo diện tích và vị trí lắp đặt.</p><a href="#/lien-he" class="textbtn small" style="margin-top:12px">Liên hệ CAMPRO ${icon('arrow')}</a></div></aside><div><div class="catalogtop"><span class="resultcount"><b>${ps.length}</b> sản phẩm${catalog.q?' cho “'+esc(catalog.q)+'”':''}</span><button class="btn light smallbtn filtertoggle" data-action="show-filter">${icon('filter')} Bộ lọc</button><label>Sắp xếp: <select aria-label="Sắp xếp sản phẩm" data-filter="sort">${[['featured','Đề xuất'],['asc','Giá: thấp đến cao'],['desc','Giá: cao đến thấp'],['name','Tên sản phẩm']].map(([v,t])=>`<option value="${v}" ${catalog.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${catalog.cats.length||catalog.resolution.length||catalog.q||catalog.price?`<div class="activefilters"><button data-action="reset-filter">Xóa tất cả bộ lọc ×</button>${catalog.cats.map(c=>`<span class="badge neutral">${esc(c)}</span>`).join('')}</div>`:''}<div class="productgrid cataloggrid">${ps.length?ps.map(card).join(''):empty('Không tìm thấy camera phù hợp','Thử từ khóa ngắn hơn hoặc bỏ bớt điều kiện lọc.','/san-pham','Xem tất cả camera')}</div><p class="muted small" style="margin-top:24px">Hiển thị ${ps.length} / ${db.products.filter(p=>p.active).length} sản phẩm · Giá minh họa cho bản xem thử</p></div></div></div>`}
function detailPage(id){const p=product(id);if(!p||!p.active)return `<div class="wrap">${empty('Không tìm thấy sản phẩm','Sản phẩm không còn được hiển thị.')}</div>`;return `<div class="wrap">${crumb(p.name,true)}<div class="detailgrid"><div class="detailimage"><span class="tag">${esc(p.tag)}</span><img src="./assets/${esc(p.image)}" alt="${esc(p.name)}" width="430" height="430"></div><div class="detailinfo"><div class="eyebrow">${esc(p.brand)} · ${esc(p.category)}</div><h1>${esc(p.name)}</h1><p class="subtitle muted">${esc(p.subtitle)}</p><span class="stock ${p.stock?'':'out'}">${p.stock?'Có sẵn '+p.stock+' sản phẩm':'Tạm hết hàng'}</span><div class="prices"><strong class="price">${money(p.price)}</strong>${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del><span class="badge danger">Tiết kiệm ${money(p.oldPrice-p.price)}</span>`:''}</div><div class="featureslist"><span>${icon('check')} Hình ảnh ${esc(p.resolution)}</span><span>${icon('check')} Kết nối ${esc(p.connection)}</span><span>${icon('check')} Quan sát ${esc(p.angle.toLowerCase())} · Ban đêm ${esc(p.night.toLowerCase())}</span></div><label class="small muted" for="detail-qty">Số lượng</label><div class="detailactions"><div class="quantity"><button data-detailqty="-1" aria-label="Giảm số lượng">−</button><input id="detail-qty" value="1" type="number" min="1" max="${p.stock||1}" aria-label="Số lượng mua"><button data-detailqty="1" aria-label="Tăng số lượng">+</button></div><button class="btn redbtn" data-add="${p.id}" data-detail="true" ${p.stock?'':'disabled'}>${icon('cart')} Thêm vào giỏ</button></div><button class="btn full light" data-buy="${p.id}" ${p.stock?'':'disabled'}>Mua ngay</button><div class="detailpolicy"><span>✓ Kiểm tra đơn hàng trước khi xác nhận</span><span>✓ Hỗ trợ tư vấn lựa chọn và cài đặt</span><a href="#/chinh-sach" class="textbtn">Thông tin giao hàng & bảo hành</a></div></div></div><section class="section contentcols"><div><h2>Hiểu rõ trước khi chọn</h2><p>${esc(p.description)}</p><p>Lựa chọn vị trí lắp đặt có nguồn điện và kết nối mạng phù hợp. Liên hệ tư vấn nếu bạn cần bố trí nhiều camera hoặc chưa rõ phương án lưu trữ.</p><a class="textbtn" href="#/lien-he" style="margin-top:20px">Tư vấn cho không gian của tôi ${icon('arrow')}</a></div><div><h2>Thông tin thiết bị</h2><table class="spec-table">${[['Thương hiệu',p.brand],['Độ phân giải',p.resolution],['Kết nối',p.connection],['Vị trí lắp đặt',p.category],['Góc quan sát',p.angle],['Quan sát ban đêm',p.night]].map(([a,b])=>`<tr><td>${a}</td><td>${esc(b)}</td></tr>`).join('')}</table></div></section><section class="section"><div class="sectionhead"><h2>Có thể bạn cũng quan tâm</h2><a href="#/san-pham">Xem tất cả ${icon('arrow')}</a></div><div class="productgrid">${db.products.filter(x=>x.active&&x.id!==p.id).slice(0,4).map(card).join('')}</div></section></div>`}
function quantity(p){return `<div class="quantity"><button data-qty="${p.id}" data-delta="-1" aria-label="Giảm số lượng ${esc(p.name)}">−</button><input type="number" min="1" max="${p.stock}" value="${p.quantity}" data-cartqty="${p.id}" aria-label="Số lượng ${esc(p.name)}"><button data-qty="${p.id}" data-delta="1" aria-label="Tăng số lượng ${esc(p.name)}">+</button></div>`}
function summary(checkout=false){const sub=subtotal(),discount=coupon?discountFor(coupon,sub).amount:0;return `<aside class="summary"><h3>Tóm tắt đơn hàng</h3>${checkout?cartItems().map(p=>`<div class="between"><span>${esc(p.name)} × ${p.quantity}</span><b>${money(p.price*p.quantity)}</b></div>`).join(''):''}<div class="between"><span>Tạm tính</span><b>${money(sub)}</b></div><div class="between"><span>Giao hàng</span><span class="green">Miễn phí (demo)</span></div><div class="couponfield"><input id="coupon-code" placeholder="Mã giảm giá" value="${esc(coupon)}" aria-label="Mã giảm giá"><button class="btn light smallbtn" data-action="apply-coupon" type="button">Áp dụng</button></div><div class="small muted">Thử mã <b>CAMPRO10</b> · Giảm 10%, tối đa 200.000₫</div>${discount?`<div class="between green"><span>Giảm giá (${esc(coupon)})</span><b>−${money(discount)}</b></div>`:''}<div class="between total"><span>Tổng cộng</span><b>${money(sub-discount)}</b></div>${checkout?`<button class="btn redbtn full" type="submit" form="checkout-form">Xác nhận đặt hàng ${icon('arrow')}</button><small>Đây là thao tác thử. Không thanh toán hoặc gửi đơn hàng thật.</small>`:`<a class="btn redbtn full" href="#/thanh-toan">Tiến hành đặt hàng ${icon('arrow')}</a><small>${icon('lock')} Thông tin rõ ràng trước khi xác nhận.</small>`}</aside>`}
function cartPage(){const items=cartItems();return `<div class="wrap">${crumb('Giỏ hàng')}${title('Giỏ hàng của bạn',items.length+' sản phẩm · Kiểm tra lại lựa chọn trước khi đặt hàng.')} ${items.length?`<div class="cartlayout"><div>${items.map(p=>`<div class="cartrow"><a href="#/san-pham/${p.id}"><img src="./assets/${esc(p.image)}" alt="${esc(p.name)}"></a><div><h3><a href="#/san-pham/${p.id}">${esc(p.name)}</a></h3><p class="muted">${esc(p.resolution)} · ${esc(p.category)}</p>${quantity(p)}</div><div style="text-align:right"><div class="price">${money(p.price*p.quantity)}</div><button class="textbtn" data-remove="${p.id}">Xóa</button></div></div>`).join('')}<div class="between" style="margin-top:20px"><a href="#/san-pham" class="textbtn small">${icon('back')} Tiếp tục mua sắm</a><button class="textbtn small" data-action="clear-cart">Xóa giỏ hàng</button></div></div>${summary()}</div>`:empty('Giỏ hàng đang trống','Bắt đầu bằng một chiếc camera phù hợp với nhu cầu của bạn.')}</div>`}
function checkoutPage(){if(!db.session){returnAfterLogin='/thanh-toan';return authPage(false,'Đăng nhập để tiếp tục đặt hàng.')}if(!cartItems().length)return `<div class="wrap">${crumb('Đặt hàng')}${empty('Chưa có sản phẩm để đặt hàng','Hãy thêm sản phẩm vào giỏ trước khi tiếp tục.')}</div>`;const u=db.session;return `<div class="wrap">${crumb('Đặt hàng')}<div class="steps"><a href="#/gio-hang">01 · Giỏ hàng</a>${icon('chevron')}<span class="active">02 · Thông tin đặt hàng</span>${icon('chevron')}<span>03 · Hoàn tất</span></div>${title('Hoàn tất đơn hàng')}<div class="cartlayout"><form id="checkout-form"><section class="checkoutsection"><h3>01. Thông tin giao hàng</h3><div class="formgrid">${field('Họ và tên','name',u.name,'text',true)}${field('Số điện thoại','phone',u.phone,'tel',true,'pattern="[0-9 +()-]{9,15}"')}${field('Email','email',u.email,'email',true)}${field('Địa chỉ nhận hàng','address',u.address,'text',true)}<label class="field span2">Ghi chú đơn hàng<textarea name="note" placeholder="Thời gian giao thuận tiện, hướng dẫn tìm địa chỉ..."></textarea></label></div></section><section class="checkoutsection"><h3>02. Phương thức thanh toán</h3><label class="radiooption"><input type="radio" name="payment" value="COD" checked><span><b>Thanh toán khi nhận hàng</b><small>Kiểm tra hàng trước khi thanh toán.</small></span></label><label class="radiooption"><input type="radio" name="payment" value="Chuyển khoản"><span><b>Chuyển khoản ngân hàng</b><small>Bản thử nghiệm chỉ ghi nhận lựa chọn, không chuyển tiền.</small></span></label></section><p class="small muted">Dữ liệu chỉ lưu trên trình duyệt. Hãy dùng thông tin mẫu khi trải nghiệm.</p></form>${summary(true)}</div></div>`}
function field(label,name,value='',type='text',required=true,extra=''){return `<label class="field">${label}${required?' *':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function authPage(register=false,note=''){const adminLogin=note.toLowerCase().includes('quản trị');return `<div class="wrap">${crumb(register?'Đăng ký':'Đăng nhập')}<div class="auth"><h1>${register?'Tạo tài khoản':adminLogin?'Đăng nhập quản trị':'Chào mừng trở lại'}</h1><p>${note||'Theo dõi đơn hàng và lưu thông tin mua sắm của bạn.'}</p><form id="${register?'register':'login'}-form" class="stack">${register?field('Họ và tên','name'):''}${field('Email','email',adminLogin?'admin@campro.vn':'','email')}${field('Mật khẩu','password','','password',true,'minlength="6" autocomplete="'+(register?'new-password':'current-password')+'"')}${register?field('Xác nhận mật khẩu','confirm','','password',true,'minlength="6"'):''}<p id="auth-error" class="error" role="alert"></p><button class="btn redbtn full">${register?'Đăng ký tài khoản':'Đăng nhập'}</button></form>${adminLogin?'<div class="notice">Tài khoản quản trị: admin@campro.vn · Mật khẩu: Admin@123</div>':`<p class="switch">${register?'Đã có tài khoản? <a href="#/dang-nhap">Đăng nhập</a>':'Chưa có tài khoản? <a href="#/dang-ky">Đăng ký ngay</a>'}</p><div class="notice">Tài khoản mẫu: minhanh@example.com · Mật khẩu: 123456</div><button class="btn light full" data-action="demo-login" style="margin-top:16px">Dùng tài khoản khách hàng mẫu ${icon('arrow')}</button>`}</div></div>`}
function accountNav(active){return `<aside class="accountnav"><a href="#/tai-khoan" class="${active==='profile'?'active':''}">${icon('user')} Hồ sơ cá nhân</a><a href="#/don-hang" class="${active==='orders'?'active':''}">${icon('orders')} Đơn hàng của tôi</a><button class="textbtn" data-action="logout">${icon('exit')} Đăng xuất</button></aside>`}
function profilePage(){if(!db.session)return authPage();const u=db.session;return `<div class="wrap">${crumb('Tài khoản')}${title('Tài khoản của bạn','Quản lý thông tin và theo dõi các đơn hàng.')}<div class="accountlayout">${accountNav('profile')}<div><section class="checkoutsection"><h3>Thông tin cá nhân</h3><form id="profile-form" class="formgrid">${field('Họ và tên','name',u.name)}${field('Email','email',u.email,'email',true,'readonly')}${field('Số điện thoại','phone',u.phone,'tel',false)}${field('Địa chỉ','address',u.address,'text',false)}<div class="span2"><button class="btn redbtn">Lưu thay đổi</button></div></form></section><section class="checkoutsection"><h3>Đổi mật khẩu</h3><p class="small muted" style="margin-bottom:18px">Mật khẩu được mã hóa và lưu trong MySQL.</p><form id="password-form" class="formgrid">${field('Mật khẩu hiện tại','old','','password')}${field('Mật khẩu mới','password','','password',true,'minlength="6"')}${field('Xác nhận mật khẩu mới','confirm','','password',true,'minlength="6"')}<div class="span2"><button class="btn light">Cập nhật mật khẩu</button></div></form></section></div></div></div>`}
function myOrders(){if(!db.session)return authPage(false,'Đăng nhập để xem đơn hàng của bạn.');const orders=db.orders.filter(o=>o.email===db.session.email);return `<div class="wrap">${crumb('Đơn hàng')}${title('Đơn hàng của tôi','Theo dõi và quản lý những đơn hàng đã đặt.')}<div class="accountlayout">${accountNav('orders')}<div>${orders.length?orders.map(o=>`<article class="ordercard"><div class="between orderhead"><div><b>#${o.id}</b><span class="small muted"> · ${o.date}</span></div>${badge(o.status)}</div>${o.items.map(p=>`<div class="flex" style="margin:10px 0"><img src="./assets/${esc(p.image)}" alt=""><div><b>${esc(p.name)}</b><p class="small muted">${p.quantity} × ${money(p.price)}</p></div></div>`).join('')}<div class="between" style="margin-top:20px"><strong>${money(o.total)}</strong><a class="btn light smallbtn" href="#/don-hang/${o.id}">Xem chi tiết ${icon('arrow')}</a></div></article>`).join(''):empty('Bạn chưa có đơn hàng','Đơn hàng mới sẽ xuất hiện tại đây.')}</div></div></div>`}
function orderDetail(id,admin=false){const o=db.orders.find(o=>o.id===id&&(admin||o.email===db.session?.email));if(!o)return empty('Không tìm thấy đơn hàng','Vui lòng kiểm tra tài khoản hoặc mã đơn.','/don-hang','Về danh sách đơn');return `${title('Đơn hàng #'+esc(o.id),'Đặt ngày '+o.date)}<div class="between">${badge(o.status)}<span class="small muted">${esc(o.payment)} · ${o.paid?'Đã thanh toán':'Chưa thanh toán'}</span></div><div class="statusline">${['Chờ xử lý','Đã xác nhận','Đang giao','Đã giao','Hoàn thành'].map((s,i)=>`<div class="statusstep ${o.status!=='Đã hủy'&&i<=['Chờ xử lý','Đã xác nhận','Đang giao','Đã giao','Hoàn thành'].indexOf(o.status)?'done':''}">${s}</div>`).join('')}</div><div class="admingrid"><section class="panel"><h3>Sản phẩm trong đơn</h3>${o.items.map(p=>`<div class="cartrow"><img src="./assets/${esc(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p class="small muted">Số lượng: ${p.quantity}</p></div><b>${money(p.price*p.quantity)}</b></div>`).join('')}<div class="between" style="margin-top:20px"><span>Giảm giá</span><b>−${money(o.discount)}</b></div><div class="between" style="margin-top:15px"><strong>Tổng thanh toán</strong><strong class="price">${money(o.total)}</strong></div></section><section class="panel"><h3>Thông tin người nhận</h3><p style="margin-top:18px"><b>${esc(o.customer)}</b></p><p class="small muted">${esc(o.phone)}<br>${esc(o.email)}</p><p style="margin-top:12px">${esc(o.address)}</p>${o.note?`<p class="small muted" style="margin-top:12px">Ghi chú: ${esc(o.note)}</p>`:''}${admin?`<form id="order-status-form" data-id="${o.id}" class="stack" style="margin-top:25px"><label class="field">Trạng thái đơn hàng<select name="status">${['Chờ xử lý','Đã xác nhận','Đang giao','Đã giao','Hoàn thành','Đã hủy'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="flex small"><input type="checkbox" name="paid" ${o.paid?'checked':''}> Đã thanh toán</label><button class="btn redbtn">Lưu trạng thái</button></form>`:o.status==='Chờ xử lý'?`<button class="btn light full" style="margin-top:25px" data-cancelorder="${o.id}">Hủy đơn hàng</button>`:''}</section></div>`}
function successPage(id){const o=db.orders.find(o=>o.id===id&&o.email===db.session?.email);return `<div class="wrap"><div class="successpage"><div class="successicon">${icon('check')}</div><h1>Đã ghi nhận đơn hàng!</h1><p>Đơn hàng <b>#${esc(o?.id||'')}</b> đã được lưu vào hệ thống.<br>Bạn có thể theo dõi trạng thái trong mục đơn hàng.</p><div class="flex" style="justify-content:center;flex-wrap:wrap"><a class="btn redbtn" href="#/don-hang/${esc(id)}">Xem đơn hàng ${icon('arrow')}</a><a class="btn light" href="#/san-pham">Tiếp tục mua sắm</a></div></div></div>`}
function comparePage(){const ps=db.compare.map(product).filter(Boolean);return `<div class="wrap">${crumb('So sánh camera')}${title('Đặt cạnh nhau. Chọn dễ hơn.','So sánh tối đa 3 camera theo các thông tin quan trọng.')}${ps.length?`<div class="comparetable"><table><tr><th>Sản phẩm</th>${ps.map(p=>`<td><img src="./assets/${esc(p.image)}" alt="${esc(p.name)}"><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><button class="btn redbtn smallbtn" data-add="${p.id}" ${p.stock?'':'disabled'}>Thêm vào giỏ</button></td>`).join('')}</tr>${[['Độ phân giải','resolution'],['Vị trí lắp','category'],['Kết nối','connection'],['Góc quan sát','angle'],['Ban đêm','night']].map(([label,k])=>`<tr><th>${label}</th>${ps.map(p=>`<td>${esc(p[k])}</td>`).join('')}</tr>`).join('')}<tr><th>Tình trạng</th>${ps.map(p=>`<td>${p.stock?'Sẵn hàng':'Hết hàng'}</td>`).join('')}</tr></table></div>`:empty('Chưa chọn camera để so sánh','Đánh dấu “So sánh sản phẩm” trên thẻ camera bạn quan tâm.')}</div>`}
function articlesGrid(){return `<div class="articles">${db.articles.filter(a=>a.published).map(a=>`<a href="#/tin-tuc/${a.id}" class="articlecard"><div class="articlephoto"><img src="./assets/${esc(a.image)}" alt="" loading="lazy"></div><div class="eyebrow">${esc(a.category)}</div><h3>${esc(a.title)} ↗</h3></a>`).join('')}</div>`}
function newsPage(id){if(!id)return `<div class="wrap">${crumb('Góc tư vấn')}${title('Góc tư vấn camera','Những điều hữu ích để lựa chọn và sử dụng camera đúng nhu cầu.')}${articlesGrid()}</div>`;const a=db.articles.find(a=>a.id===Number(id)&&a.published);return a?`<div class="wrap">${crumb('Góc tư vấn')}<article class="articlebody"><div class="eyebrow muted">${esc(a.category)}</div><h1>${esc(a.title)}</h1><img src="./assets/${esc(a.image)}" alt="Camera minh họa">${a.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}<a class="btn light" href="#/tin-tuc">${icon('back')} Xem bài viết khác</a></article></div>`:empty('Bài viết chưa có sẵn','Hãy xem các bài viết khác.','/tin-tuc','Về góc tư vấn')}
function contactPage(){return `<div class="wrap">${crumb('Liên hệ')}${title('Cùng tìm giải pháp phù hợp.','Gửi nhu cầu của bạn để đội ngũ tư vấn có đủ thông tin hỗ trợ.')}<div class="contactgrid"><aside class="contactinfo"><div class="eyebrow" style="color:#a5b09c;margin-bottom:17px">CAMPRO LUÔN LẮNG NGHE</div><h2>Bắt đầu từ<br>không gian của bạn.</h2><p>Nhà ở, cửa hàng hay văn phòng — mỗi nơi cần một cách quan sát riêng.</p><h3>Chuẩn bị trước khi tư vấn</h3><p>Diện tích cần quan sát, vị trí trong hay ngoài trời, số lượng camera dự kiến và ngân sách.</p><h3>Thông tin minh bạch</h3><p>Yêu cầu được lưu trong hệ thống và chuyển đến khu vực quản trị để xử lý.</p></aside><form id="contact-form" class="formgrid">${field('Họ và tên','name')}${field('Email','email','','email')}${field('Số điện thoại','phone','','tel',false)}<label class="field">Bạn cần hỗ trợ về<select name="subject"><option>Tư vấn chọn camera</option><option>Tư vấn lắp đặt</option><option>Hỗ trợ đơn hàng</option><option>Góp ý khác</option></select></label><label class="field span2">Nội dung yêu cầu *<textarea name="message" required minlength="10" placeholder="Ví dụ: Tôi cần 2 camera cho cửa hàng 40m², có sẵn Wi-Fi..."></textarea></label><div class="span2"><button class="btn redbtn">Gửi yêu cầu tư vấn ${icon('arrow')}</button><p class="small muted" style="margin-top:12px">CAMPRO sẽ phản hồi theo thông tin liên hệ bạn cung cấp.</p></div></form></div></div>`}
function policyPage(){return `<div class="wrap">${crumb('Thông tin mua hàng')}<div class="articlebody">${title('Thông tin mua hàng')}<div class="notice">Chính sách dưới đây minh họa cách trình bày cho giao diện. Cửa hàng cần xác nhận nội dung chính thức trước khi kinh doanh.</div><h3 style="margin-top:30px">Giao hàng</h3><p>Thông tin người nhận và địa chỉ được kiểm tra trước khi xác nhận. Phí giao hàng cần được hiển thị rõ tại bước đặt hàng; bản thử đang áp dụng miễn phí giao hàng.</p><h3>Thanh toán</h3><p>Giao diện hỗ trợ lựa chọn COD hoặc chuyển khoản. Chưa có giao dịch tiền thật hay kết nối ngân hàng trong bản thử.</p><h3>Bảo hành và đổi trả</h3><p>Điều kiện bảo hành phụ thuộc thiết bị và nhà cung cấp. Khách hàng cần được cung cấp thời hạn, phạm vi bảo hành và quy trình xử lý trước khi mua.</p><a class="btn" href="#/lien-he">Liên hệ tư vấn ${icon('arrow')}</a></div></div>`}
const adminNav=[['','Tổng quan','grid'],['orders','Đơn hàng','orders'],['products','Sản phẩm','box'],['categories','Danh mục','grid'],['suppliers','Nhà cung cấp','building'],['customers','Khách hàng','user'],['coupons','Mã giảm giá','tag'],['news','Bài viết','news'],['contacts','Liên hệ','mail'],['reports','Báo cáo doanh thu','chart']];
function adminShell(view,content){const name=adminNav.find(n=>n[0]===view)?.[1]||'Đơn hàng';return `<div class="adminshell"><aside class="adminside">${logo()}<div class="navlabel">QUẢN LÝ CỬA HÀNG</div><nav>${adminNav.map(([slug,label,i])=>`<a href="#/admin${slug?'/'+slug:''}" class="${view===slug?'active':''}" title="${label}">${icon(i)}<span>${label}</span></a>`).join('')}</nav><div class="sidebottom"><a href="#/">${icon('exit')}<span>Về cửa hàng</span></a><a href="#/admin" data-action="reset-demo">${icon('back')}<span>Khôi phục dữ liệu mẫu</span></a></div></aside><main class="adminmain"><header class="adminheader"><div class="crumb">Không gian quản trị <span style="margin:0 8px">/</span> <b style="color:var(--ink)">${name}</b></div><div class="profile"><span class="badge success">MYSQL</span><div class="avatar">AD</div><div><strong>Quản trị viên</strong><small class="muted">Cửa hàng CAMPRO</small></div></div></header><div class="admincontent">${content}<p class="adminnote">Hệ thống quản trị CAMPRO · Thay đổi được lưu vào MySQL qua ASP.NET Core</p></div></main></div>`}
function stat(label,value,info,i='chart',highlight=false){return `<div class="statcard ${highlight?'highlight':''}"><div class="between"><span>${label}</span>${icon(i)}</div><div class="statvalue">${value}</div><p>${info}</p></div>`}
function revenueChart(orders){const points=Array.from({length:7},(_,i)=>{const date='2026-09-'+String(15+i).padStart(2,'0');return{label:(15+i)+'/09',value:orders.filter(o=>o.date===date&&['Hoàn thành','Đã giao'].includes(o.status)).reduce((s,o)=>s+o.total,0)}}),max=Math.max(...points.map(p=>p.value),1000000);return `<div class="chart"><div class="chartgrid">${[1,.75,.5,.25,0].map(v=>`<div><span>${(max*v/1e6).toFixed(1)} tr</span></div>`).join('')}</div><div class="bars">${points.map(p=>`<div class="bar" style="height:${Math.max(1,p.value/max*100)}%" title="${p.label}: ${money(p.value)}"><span>${p.label}</span>${p.value?`<strong>${(p.value/1e6).toFixed(2)} tr</strong>`:''}</div>`).join('')}</div></div>`}
function orderTable(orders){return `<div class="tablewrap"><table class="datatable"><thead><tr><th>Mã đơn hàng</th><th>Khách hàng</th><th>Ngày đặt</th><th>Giá trị</th><th>Trạng thái</th><th></th></tr></thead><tbody>${orders.length?orders.map(o=>`<tr><td><a href="#/admin/orders/${o.id}"><strong>#${o.id}</strong></a></td><td>${esc(o.customer)}<small>${esc(o.payment)}</small></td><td>${o.date.split('-').reverse().join('/')}</td><td><strong>${money(o.total)}</strong></td><td>${badge(o.status)}</td><td><a class="iconbtn" href="#/admin/orders/${o.id}" aria-label="Xem đơn ${o.id}">${icon('arrow')}</a></td></tr>`).join(''):'<tr><td colspan="6">Không có đơn hàng phù hợp.</td></tr>'}</tbody></table></div>`}
function dashboard(){const revenue=db.orders.filter(o=>['Đã giao','Hoàn thành'].includes(o.status)).reduce((s,o)=>s+o.total,0),pending=db.orders.filter(o=>o.status==='Chờ xử lý').length;return `<div class="adminintro">${title('Tổng quan cửa hàng','Chào bạn, đây là hoạt động mới nhất tại CAMPRO.')}<span class="datecontrol">${icon('calendar')} Tháng 09, 2026</span></div><div class="statsgrid">${stat('Doanh thu ghi nhận',money(revenue),'Từ đơn đã giao và hoàn thành','chart',true)}${stat('Tổng đơn hàng',db.orders.length,pending+' đơn cần xử lý','orders')}${stat('Sản phẩm đang bán',db.products.filter(p=>p.active).length,db.products.filter(p=>p.stock<10).length+' sản phẩm cần kiểm tra tồn kho','box')}${stat('Khách hàng',db.customers.length,'Tài khoản trong cửa hàng','user')}</div><div class="dashboardgrid"><section class="panel"><div class="between"><div><h3>Doanh thu 7 ngày</h3><p class="panelsub">15 – 21 tháng 09, 2026</p></div><span class="small muted">VND</span></div>${revenueChart(db.orders)}</section><section class="panel"><h3>Cần bạn xử lý</h3><p class="panelsub">Ưu tiên các công việc đang chờ</p><div class="taskrow"><span>Đơn hàng mới<br><a href="#/admin/orders">Xem danh sách →</a></span><strong>${pending.toString().padStart(2,'0')}</strong></div><div class="taskrow"><span>Sản phẩm sắp hết hàng<br><a href="#/admin/products">Kiểm tra tồn kho →</a></span><strong>${db.products.filter(p=>p.stock<10).length.toString().padStart(2,'0')}</strong></div><div class="taskrow"><span>Yêu cầu tư vấn<br><a href="#/admin/contacts">Xem liên hệ →</a></span><strong>${db.contacts.filter(c=>c.status==='Chưa xử lý').length.toString().padStart(2,'0')}</strong></div></section></div><section class="panel tablepanel"><div class="tabletitle"><h3>Đơn hàng gần đây</h3><a href="#/admin/orders">Tất cả đơn hàng →</a></div>${orderTable(db.orders.slice(0,5))}<div class="tablefooter"><span>${db.orders.length} đơn hàng trong hệ thống</span><span>Dữ liệu minh họa</span></div></section>`}
function adminToolbar(placeholder,statusOptions=[]){return `<div class="admintoolbar"><form id="admin-search-form" class="searchbox"><input name="search" placeholder="${placeholder}" value="${esc(adminSearch)}" aria-label="${placeholder}"><button aria-label="Tìm kiếm">${icon('search')}</button></form>${statusOptions.length?`<select id="admin-status" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option>${statusOptions.map(s=>`<option ${adminStatus===s?'selected':''}>${s}</option>`).join('')}</select>`:''}</div>`}
const matches=(...v)=>v.join(' ').toLowerCase().includes(adminSearch.toLowerCase());
function adminOrders(){const os=db.orders.filter(o=>matches(o.id,o.customer,o.phone)&&(!adminStatus||o.status===adminStatus));return `${title('Đơn hàng','Theo dõi và xử lý đơn hàng từ lúc tiếp nhận đến khi giao thành công.')}${adminToolbar('Tìm mã đơn, khách hàng, điện thoại...',['Chờ xử lý','Đã xác nhận','Đang giao','Đã giao','Hoàn thành','Đã hủy'])}<section class="panel tablepanel">${orderTable(os)}<div class="tablefooter">Hiển thị ${os.length} đơn hàng</div></section>`}
function adminProducts(){const ps=db.products.filter(p=>matches(p.name,p.category)&&(!adminStatus||(adminStatus==='Đang bán'?p.active:adminStatus==='Đã ẩn'?!p.active:p.stock<10)));return `<div class="adminintro">${title('Sản phẩm','Quản lý thông tin, giá bán và số lượng tồn kho.')}<button class="btn redbtn" data-edit="products" data-id="new">${icon('plus')} Thêm sản phẩm</button></div>${adminToolbar('Tìm tên sản phẩm hoặc danh mục...',['Đang bán','Đã ẩn','Sắp hết hàng'])}<section class="panel tablepanel"><div class="tablewrap"><table class="datatable"><thead><tr><th>Sản phẩm</th><th>Danh mục</th><th>Giá bán</th><th>Tồn kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="productcell"><img src="./assets/${esc(p.image)}" alt=""><div><strong>${esc(p.name)}</strong><small>CP-${String(p.id).padStart(4,'0')} · ${esc(p.resolution)}</small></div></div></td><td>${esc(p.category)}</td><td><strong>${money(p.price)}</strong></td><td><span class="${p.stock<10?'red':''}">${p.stock} sản phẩm</span></td><td><button class="textbtn" data-toggle="products" data-id="${p.id}"><span class="badge ${p.active?'success':'neutral'}">${p.active?'Đang bán':'Đã ẩn'}</span></button></td><td><button class="iconbtn" data-edit="products" data-id="${p.id}" aria-label="Sửa ${esc(p.name)}">${icon('edit')}</button><button class="iconbtn" data-delete="products" data-id="${p.id}" aria-label="Xóa ${esc(p.name)}">${icon('trash')}</button></td></tr>`).join('')||'<tr><td colspan="6">Không có sản phẩm phù hợp.</td></tr>'}</tbody></table></div><div class="tablefooter"><span>${ps.length} sản phẩm</span><span>Nhấn trạng thái để ẩn / hiện</span></div></section>`}
function adminCustomers(){const cs=db.customers.filter(c=>matches(c.name,c.email,c.phone)&&(!adminStatus||(adminStatus==='Hoạt động'?c.active:!c.active)));return `${title('Khách hàng','Thông tin liên hệ, trạng thái tài khoản và lịch sử mua hàng.')}${adminToolbar('Tìm tên, email hoặc điện thoại...',['Hoạt động','Đã khóa'])}<section class="panel tablepanel"><div class="tablewrap"><table class="datatable"><thead><tr><th>Khách hàng</th><th>Điện thoại</th><th>Đơn hàng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${cs.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.email)}</small></td><td>${esc(c.phone)||'—'}</td><td><button class="textbtn" data-customer-orders="${c.id}">${db.orders.filter(o=>o.email===c.email).length} đơn hàng</button></td><td><button class="textbtn" data-toggle="customers" data-id="${c.id}"><span class="badge ${c.active?'success':'neutral'}">${c.active?'Hoạt động':'Đã khóa'}</span></button></td><td><button class="iconbtn" data-edit="customers" data-id="${c.id}" aria-label="Sửa khách hàng">${icon('edit')}</button><button class="iconbtn" data-delete="customers" data-id="${c.id}" aria-label="Xóa khách hàng">${icon('trash')}</button></td></tr>`).join('')||'<tr><td colspan="5">Không tìm thấy khách hàng.</td></tr>'}</tbody></table></div></section>`}
function adminGeneric(type){const labels={categories:['Danh mục sản phẩm','Tổ chức camera theo vị trí và nhu cầu sử dụng.','Thêm danh mục'],suppliers:['Nhà cung cấp','Quản lý đối tác và thông tin liên hệ.','Thêm nhà cung cấp'],coupons:['Mã giảm giá','Thiết lập ưu đãi và điều kiện áp dụng.','Tạo mã giảm giá'],news:['Bài viết','Quản lý nội dung hướng dẫn và tư vấn chọn mua.','Viết bài mới'],contacts:['Liên hệ','Tiếp nhận và phản hồi yêu cầu tư vấn của khách hàng.','']};const [h,p,b]=labels[type],items=db[type].filter(x=>matches(x.name||x.title||x.code,x.email||'',x.subject||''));const cells=x=>type==='categories'?`<td><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small></td><td>${db.products.filter(p=>p.category===x.name).length} sản phẩm</td><td><span class="badge ${x.active?'success':'neutral'}">${x.active?'Hiển thị':'Ẩn'}</span></td>`:type==='suppliers'?`<td><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small></td><td>${esc(x.email)}<small>${esc(x.phone)}</small></td><td><span class="badge ${x.active?'success':'neutral'}">${x.active?'Hoạt động':'Ẩn'}</span></td>`:type==='coupons'?`<td><strong>${esc(x.code)}</strong><small>Đơn tối thiểu ${money(x.min)}</small></td><td>${x.type==='percent'?x.value+'%':money(x.value)}<small>Tối đa ${money(x.max||x.value)}</small></td><td><button class="textbtn" data-toggle="coupons" data-id="${x.id}"><span class="badge ${x.active?'success':'neutral'}">${x.active?'Đang áp dụng':'Tạm dừng'}</span></button></td>`:type==='news'?`<td><strong>${esc(x.title)}</strong><small>${esc(x.category)}</small></td><td><span class="badge ${x.published?'success':'neutral'}">${x.published?'Đã công bố':'Bản nháp'}</span></td>`:`<td><strong>${esc(x.name)}</strong><small>${esc(x.email)}</small></td><td>${esc(x.subject)}</td><td>${badge(x.status)}</td>`;const heads={categories:['Danh mục','Sản phẩm','Trạng thái'],suppliers:['Nhà cung cấp','Liên hệ','Trạng thái'],coupons:['Mã giảm giá','Mức giảm','Trạng thái'],news:['Bài viết','Trạng thái'],contacts:['Người gửi','Chủ đề','Trạng thái']}[type];return `<div class="adminintro">${title(h,p)}${b?`<button class="btn redbtn" data-edit="${type}" data-id="new">${icon('plus')} ${b}</button>`:''}</div>${adminToolbar('Tìm kiếm '+h.toLowerCase()+'...')}<section class="panel tablepanel"><div class="tablewrap"><table class="datatable"><thead><tr>${heads.map(t=>`<th>${t}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${items.map(x=>`<tr>${cells(x)}<td><button class="iconbtn" data-edit="${type}" data-id="${x.id}" aria-label="${type==='contacts'?'Xem và trả lời':'Chỉnh sửa'}">${icon(type==='contacts'?'mail':'edit')}</button><button class="iconbtn" data-delete="${type}" data-id="${x.id}" aria-label="Xóa">${icon('trash')}</button></td></tr>`).join('')||`<tr><td colspan="${heads.length+1}">Chưa có dữ liệu phù hợp.</td></tr>`}</tbody></table></div><div class="tablefooter">${items.length} bản ghi</div></section>`}
function reportOrders(){return db.orders.filter(o=>o.date>=reportFrom&&o.date<=reportTo)}
function reportsPage(){const os=reportOrders(),completed=os.filter(o=>['Đã giao','Hoàn thành'].includes(o.status)),rev=completed.reduce((s,o)=>s+o.total,0);const tops={};completed.forEach(o=>o.items.forEach(i=>{tops[i.name]??={name:i.name,qty:0,revenue:0};tops[i.name].qty+=i.quantity;tops[i.name].revenue+=i.price*i.quantity}));return `<div class="adminintro">${title('Báo cáo doanh thu','Đối chiếu doanh thu từ các đơn đã giao hoặc hoàn thành.')}<button class="btn light" data-action="export-report">${icon('download')} Xuất CSV</button></div><form class="reportfilter" id="report-form">${field('Từ ngày','from',reportFrom,'date')}${field('Đến ngày','to',reportTo,'date')}<button class="btn smallbtn redbtn">Áp dụng</button></form><div class="statsgrid">${stat('Doanh thu',money(rev),'Sau giảm giá','chart',true)}${stat('Đơn hàng',os.length,'Trong khoảng thời gian','orders')}${stat('Đã giao / hoàn thành',completed.length,'Đơn ghi nhận doanh thu','check')}${stat('Đơn đã hủy',os.filter(o=>o.status==='Đã hủy').length,'Không tính vào doanh thu','box')}</div><section class="panel tablepanel"><div class="tabletitle"><h3>Sản phẩm bán nhiều</h3></div><div class="tablewrap"><table class="datatable"><thead><tr><th>Sản phẩm</th><th>Số lượng đã bán</th><th>Tiền hàng trước giảm giá</th></tr></thead><tbody>${Object.values(tops).sort((a,b)=>b.qty-a.qty).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.qty}</td><td>${money(p.revenue)}</td></tr>`).join('')||'<tr><td colspan="3">Chưa có doanh thu trong thời gian này.</td></tr>'}</tbody></table></div></section><section class="panel tablepanel" style="margin-top:22px"><div class="tabletitle"><h3>Đơn hàng trong kỳ</h3></div>${orderTable(os)}</section>`}
function render(){const current=route(),[path,query]=current.split('?'),parts=path.split('/').filter(Boolean);document.title=(parts[0]==='admin'?'Quản trị':'Camera & Giải pháp an ninh')+' — CAMPRO';if(parts[0]==='admin'){if(db.session?.role!=='admin'){app.innerHTML=header()+`<main id="main">${authPage(false,'Đăng nhập tài khoản quản trị để tiếp tục.')}</main>`+footer();return}const view=parts[1]||'';let content;if(view==='orders')content=parts[2]?orderDetail(parts[2],true):adminOrders();else if(view==='products')content=adminProducts();else if(view==='customers')content=adminCustomers();else if(['categories','suppliers','coupons','news','contacts'].includes(view))content=adminGeneric(view);else if(view==='reports')content=reportsPage();else content=dashboard();app.innerHTML=adminShell(view,content);return}let content;if(!parts.length)content=home();else if(parts[0]==='san-pham')content=parts[1]?detailPage(parts[1]):catalogPage();else if(parts[0]==='gio-hang')content=cartPage();else if(parts[0]==='thanh-toan')content=checkoutPage();else if(parts[0]==='dang-nhap')content=authPage();else if(parts[0]==='dang-ky')content=authPage(true);else if(parts[0]==='tai-khoan')content=profilePage();else if(parts[0]==='don-hang')content=parts[1]?`<div class="wrap">${crumb('Chi tiết đơn hàng')}${orderDetail(parts[1])}</div>`:myOrders();else if(parts[0]==='hoan-tat')content=successPage(parts[1]);else if(parts[0]==='so-sanh')content=comparePage();else if(parts[0]==='tin-tuc')content=newsPage(parts[1]);else if(parts[0]==='lien-he')content=contactPage();else if(parts[0]==='chinh-sach')content=policyPage();else content=`<div class="wrap">${empty('Trang chưa có sẵn','Bạn có thể tiếp tục khám phá camera.')}</div>`;app.innerHTML=header()+`<main id="main">${content}</main>`+footer()+(parts[0]!=='so-sanh'?compareBar():'')}
function handleRoute(){const r=route();if(r.startsWith('/san-pham?')){const params=new URLSearchParams(r.split('?')[1]);catalog.cats=params.get('category')?[params.get('category')]:[];catalog.q=params.get('q')||''}else if(r==='/san-pham'){catalog={q:'',cats:[],resolution:[],price:'',sort:'featured'}}adminSearch='';adminStatus='';if(modal.open)modal.close();render();window.scrollTo(0,0)}
function openModal(h,body){modal.innerHTML=`<div class="modalhead"><h2>${h}</h2><button class="iconbtn" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div><div class="modalbody">${body}</div>`;modal.showModal()}
let confirmation=null;
function confirmAction(h,body,action){confirmation=action;openModal(h,`<p>${body}</p><div class="modalfoot"><button class="btn light" data-action="close-modal">Quay lại</button><button class="btn redbtn" data-action="confirm">Xác nhận</button></div>`)}
function editModal(type,id){const existing=id==='new'?null:db[type].find(x=>x.id===Number(id)),x=existing||{},labels={products:'sản phẩm',categories:'danh mục',suppliers:'nhà cung cấp',customers:'khách hàng',coupons:'mã giảm giá',news:'bài viết',contacts:'liên hệ'};let fields='';const select=(label,name,opts,value)=>`<label class="field">${label}<select name="${name}">${opts.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;if(type==='products'){fields=field('Tên sản phẩm','name',x.name)+field('Mô tả ngắn','subtitle',x.subtitle)+select('Danh mục','category',db.categories.map(c=>c.name),x.category)+field('Thương hiệu','brand',x.brand||'TP-Link Tapo')+field('Giá bán (₫)','price',x.price||0,'number',true,'min="0" step="1000"')+field('Giá gốc (₫)','oldPrice',x.oldPrice||0,'number',true,'min="0" step="1000"')+field('Tồn kho','stock',x.stock||0,'number',true,'min="0" step="1"')+select('Độ phân giải','resolution',['Full HD','2K QHD','4K'],x.resolution)+select('Kết nối','connection',['Wi-Fi','Wi-Fi / LAN','PoE'],x.connection)+select('Góc quan sát','angle',['360°','Góc cố định','Góc rộng'],x.angle)+select('Ban đêm','night',['Có màu','Hồng ngoại'],x.night)+select('Ảnh mẫu','image',['c225.jpg','c520ws.jpg','c320ws.png','c200.jpg','c425.jpg','c120.png','hikvision.png','dahua.jpg'],x.image||'c225.jpg')+`<label class="field span2">Mô tả<textarea name="description">${esc(x.description)}</textarea></label><label class="flex small span2"><input name="active" type="checkbox" ${x.active!==false?'checked':''}>Hiển thị sản phẩm trên cửa hàng</label>`}else if(type==='categories'||type==='suppliers'){fields=field('Tên','name',x.name)+field('Mô tả','description',x.description,'text',false);if(type==='suppliers')fields+=field('Email','email',x.email,'email')+field('Điện thoại','phone',x.phone,'tel',false);fields+=`<label class="flex small span2"><input name="active" type="checkbox" ${x.active!==false?'checked':''}>Đang hoạt động</label>`}else if(type==='customers'){fields=field('Họ và tên','name',x.name)+field('Email','email',x.email,'email',true,'readonly')+field('Điện thoại','phone',x.phone,'tel',false)+field('Địa chỉ','address',x.address,'text',false)}else if(type==='coupons'){fields=field('Mã giảm giá','code',x.code,'text',true,'pattern="[A-Za-z0-9]+"')+`<label class="field">Hình thức giảm<select name="type"><option value="percent" ${x.type==='percent'?'selected':''}>Phần trăm</option><option value="fixed" ${x.type==='fixed'?'selected':''}>Số tiền cố định</option></select></label>`+field('Giá trị giảm','value',x.value||10,'number',true,'min="1"')+field('Đơn hàng tối thiểu','min',x.min||0,'number',true,'min="0"')+field('Giảm tối đa (₫)','max',x.max||200000,'number',true,'min="1"')+`<label class="flex small"><input name="active" type="checkbox" ${x.active!==false?'checked':''}>Đang áp dụng</label>`}else if(type==='news'){fields=field('Tiêu đề','title',x.title)+field('Chuyên mục','category',x.category||'GÓC TƯ VẤN')+select('Ảnh bài viết','image',['c225.jpg','c520ws.jpg','c320ws.png','c200.jpg'],x.image||'c225.jpg')+`<label class="flex small"><input name="published" type="checkbox" ${x.published!==false?'checked':''}>Công bố bài viết</label><label class="field span2">Nội dung *<textarea name="body" required rows="7">${esc(x.body)}</textarea></label>`}else if(type==='contacts'){fields=`<div class="span2"><b>${esc(x.name)}</b><p>${esc(x.email)} · ${esc(x.phone)}</p><h3>${esc(x.subject)}</h3><p style="white-space:pre-wrap;margin-top:12px">${esc(x.message)}</p></div><label class="field span2">Nội dung phản hồi *<textarea name="reply" required rows="5">${esc(x.reply)}</textarea></label><div class="small muted span2">Nội dung được lưu trong bản thử, không gửi email thật.</div>`}openModal(type==='contacts'?'Chi tiết liên hệ':(existing?'Chỉnh sửa ':'Thêm ')+labels[type],`<form id="entity-form" data-type="${type}" data-id="${id}"><div class="formgrid">${fields}</div><p id="entity-error" class="error" style="margin-top:14px" role="alert"></p><div class="modalfoot"><button class="btn light" type="button" data-action="close-modal">Hủy</button><button class="btn redbtn">${type==='contacts'?'Lưu phản hồi':'Lưu thay đổi'}</button></div></form>`)}
function addToCart(id,qty=1){const p=product(id);if(!p||!p.active||!Number.isInteger(qty)||qty<1){toast('Số lượng không hợp lệ.');return false}const old=db.cart.find(c=>c.id===p.id);if((old?.quantity||0)+qty>p.stock){toast('Số lượng vượt quá tồn kho ('+p.stock+').');return false}if(old)old.quantity+=qty;else db.cart.push({id:p.id,quantity:qty});save();render();toast('Đã thêm '+p.name+' vào giỏ hàng.');return true}
function setQty(id,qty){const p=product(id),c=db.cart.find(c=>c.id===Number(id));if(!c)return;if(!Number.isInteger(qty)||qty<1||qty>p.stock){toast('Số lượng phải từ 1 đến '+p.stock+'.');render();return}c.quantity=qty;save();render()}
async function loginDemo(){try{const user=await api('/auth/login',{method:'POST',body:JSON.stringify({email:'minhanh@example.com',password:'123456'})});db.session=user;const current=db.customers.find(x=>x.id===user.id);if(current)Object.assign(current,user);save();go(returnAfterLogin||'/tai-khoan');returnAfterLogin='';toast('Đã đăng nhập tài khoản khách hàng mẫu.')}catch(error){toast(error.message)}}
function updateOrderStatus(o,status,paid){if(o.status==='Đã hủy'&&status!=='Đã hủy'){toast('Đơn đã hủy không thể mở lại.');return false}if(status==='Đã hủy'&&['Đã giao','Hoàn thành'].includes(o.status)){toast('Không thể hủy đơn đã giao hoặc hoàn thành.');return false}if(status==='Đã hủy'&&o.status!=='Đã hủy')o.items.forEach(i=>{const p=product(i.id);if(p)p.stock+=i.quantity});o.status=status;o.paid=paid;save();return true}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action="logout"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();try{await api('/auth/logout',{method:'POST',body:'{}'})}catch(error){console.error(error)}db.session=null;db.cart=[];localStorage.setItem(key,JSON.stringify(db));go('/dang-nhap');toast('Đã đăng xuất.')},true);
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;
 if(d.add){addToCart(d.add,d.detail?Number(document.querySelector('#detail-qty').value):1);return}
 if(d.buy){const qty=Number(document.querySelector('#detail-qty').value);if(addToCart(d.buy,qty)){if(!db.session)returnAfterLogin='/thanh-toan';go('/thanh-toan')}return}
 if(d.detailqty){const inp=document.querySelector('#detail-qty');inp.value=Math.max(1,Math.min(Number(inp.max),Number(inp.value)+Number(d.detailqty)));return}
 if(d.qty){const c=db.cart.find(c=>c.id===Number(d.qty));setQty(d.qty,c.quantity+Number(d.delta));return}
 if(d.remove){db.cart=db.cart.filter(c=>c.id!==Number(d.remove));save();render();toast('Đã xóa sản phẩm khỏi giỏ.');return}
 if(d.homecat){homeCategory=d.homecat;render();return}
 if(d.edit){editModal(d.edit,d.id);return}
 if(d.toggle){const x=db[d.toggle].find(x=>x.id===Number(d.id));x.active=!x.active;if(d.toggle==='customers'&&db.session?.id===x.id&&!x.active)db.session=null;save();render();toast('Đã cập nhật trạng thái.');return}
 if(d.delete){const type=d.delete,id=Number(d.id),x=db[type].find(x=>x.id===id);confirmAction('Xóa dữ liệu?',`Bạn muốn xóa “${esc(x.name||x.title||x.code)}”? Thao tác này áp dụng cho dữ liệu thử nghiệm.`,()=>{if(type==='categories'&&db.products.some(p=>p.category===x.name)){toast('Danh mục còn sản phẩm. Hãy chuyển sản phẩm sang danh mục khác trước.');return}if(type==='products'&&db.orders.some(o=>o.items.some(i=>i.id===id))){x.active=false;toast('Sản phẩm đã có trong đơn hàng: đã chuyển sang trạng thái ẩn để giữ lịch sử.')}else{db[type]=db[type].filter(x=>x.id!==id);if(type==='products'){db.cart=db.cart.filter(c=>c.id!==id);db.compare=db.compare.filter(i=>i!==id)}toast('Đã xóa dữ liệu.')}save();render()});return}
 if(d.cancelorder){const o=db.orders.find(o=>o.id===d.cancelorder&&o.email===db.session?.email);if(o?.status==='Chờ xử lý')confirmAction('Hủy đơn hàng?',`Đơn #${esc(o.id)} sẽ bị hủy. Bạn có thể đặt một đơn mới bất cứ lúc nào.`,()=>{updateOrderStatus(o,'Đã hủy',o.paid);render();toast('Đã hủy đơn và hoàn lại tồn kho.')});return}
 if(d.customerOrders){const c=db.customers.find(c=>c.id===Number(d.customerOrders));openModal('Đơn hàng của '+esc(c.name),db.orders.filter(o=>o.email===c.email).map(o=>`<a class="between" href="#/admin/orders/${o.id}" style="padding:12px 0;border-bottom:1px solid var(--line)"><b>#${o.id}</b><span>${money(o.total)}</span>${icon('arrow')}</a>`).join('')||'<p>Khách hàng chưa có đơn.</p>');return}
 if(el.getAttribute('href')==='#/thanh-toan'&&!db.session)returnAfterLogin='/thanh-toan';
 switch(d.action){case'close-modal':modal.close();break;case'confirm':modal.close();confirmation?.();confirmation=null;break;case'clear-compare':db.compare=[];save();render();break;case'show-filter':document.querySelector('#filters').classList.toggle('open');break;case'reset-filter':catalog={q:'',cats:[],resolution:[],price:'',sort:'featured'};render();break;case'clear-cart':confirmAction('Xóa giỏ hàng?','Toàn bộ sản phẩm sẽ được bỏ khỏi giỏ hàng.',()=>{db.cart=[];coupon='';save();render()});break;case'apply-coupon':{const code=document.querySelector('#coupon-code').value.trim().toUpperCase(),result=discountFor(code,subtotal());if(result.error){toast(result.error);break}coupon=code;const form=document.querySelector('#checkout-form'),values=form?Object.fromEntries(new FormData(form)):null;render();if(values){const newform=document.querySelector('#checkout-form');for(const [k,v]of Object.entries(values)){const input=newform.elements[k];if(input)input.value=v}}toast('Đã áp dụng mã '+code+'.');break}case'demo-login':loginDemo();break;case'logout':db.session=null;save();go('/dang-nhap');break;case'reset-demo':e.preventDefault();confirmAction('Khôi phục dữ liệu mẫu?','Các thay đổi, giỏ hàng và đơn hàng bạn vừa thử sẽ được xóa khỏi bản demo.',()=>{db=seed();coupon='';save();render();toast('Đã khôi phục dữ liệu mẫu.')});break;case'export-report':{const rows=[['Mã đơn','Khách hàng','Ngày đặt','Trạng thái','Tổng tiền'],...reportOrders().map(o=>[o.id,o.customer,o.date,o.status,o.total])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='CAMPRO-doanh-thu.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất báo cáo CSV.');break}}
});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.compare){const id=Number(d.compare);if(e.target.checked){if(db.compare.length>=3){e.target.checked=false;toast('Bạn có thể so sánh tối đa 3 sản phẩm.');return}db.compare.push(id)}else db.compare=db.compare.filter(v=>v!==id);save();render()}if(d.filter){const val=e.target.value;if(d.filter==='cats'||d.filter==='resolution'){catalog[d.filter]=e.target.checked?[...catalog[d.filter],val]:catalog[d.filter].filter(v=>v!==val)}else catalog[d.filter]=val;const wasOpen=document.querySelector('#filters')?.classList.contains('open');render();if(wasOpen)document.querySelector('#filters')?.classList.add('open')}if(d.cartqty)setQty(d.cartqty,Number(e.target.value));if(e.target.id==='admin-status'){adminStatus=e.target.value;render()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['login-form','register-form','password-form'].includes(form.id))return;e.preventDefault();e.stopImmediatePropagation();const values=Object.fromEntries(new FormData(form)),error=document.querySelector('#auth-error');try{if(form.id==='login-form'){const user=await api('/auth/login',{method:'POST',body:JSON.stringify({email:values.email,password:values.password})});db.session=user;const current=db.customers.find(x=>x.id===user.id);if(current)Object.assign(current,user);else if(user.role==='customer')db.customers.push(user);save();go(user.role==='admin'?'/admin':(returnAfterLogin||'/tai-khoan'));returnAfterLogin='';toast('Đăng nhập thành công.')}else if(form.id==='register-form'){if(values.password!==values.confirm){error.textContent='Mật khẩu xác nhận chưa khớp.';return}const user=await api('/auth/register',{method:'POST',body:JSON.stringify({name:values.name,email:values.email,password:values.password})});db.customers.push(user);db.session=user;save();go(returnAfterLogin||'/tai-khoan');returnAfterLogin='';toast('Đăng ký tài khoản thành công.')}else{if(values.password!==values.confirm){toast('Mật khẩu xác nhận chưa khớp.');return}await api('/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:values.old,newPassword:values.password})});form.reset();toast('Đã cập nhật mật khẩu.')}}catch(ex){if(error)error.textContent=ex.message;else toast(ex.message)}},true);
document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));switch(form.id){case'search-form':catalog.q=values.q.trim();go('/san-pham?q='+encodeURIComponent(catalog.q));break;case'admin-search-form':adminSearch=values.search.trim();render();break;case'profile-form':{Object.assign(db.session,{name:values.name.trim(),phone:values.phone,address:values.address});const c=db.customers.find(c=>c.id===db.session.id);if(c)Object.assign(c,db.session);save();render();toast('Đã lưu thông tin cá nhân.');break}case'contact-form':db.contacts.unshift({id:Date.now(),...values,status:'Chưa xử lý',reply:''});save();form.reset();openModal('Đã tiếp nhận yêu cầu',`<div class="successicon">${icon('check')}</div><p>Yêu cầu của bạn đã lưu vào hệ thống. Bạn có thể xem ở mục Liên hệ trong trang quản trị.</p><button class="btn full" data-action="close-modal">Hoàn tất</button>`);break;case'checkout-form':{if(!db.session)return;const items=cartItems();if(!items.length){toast('Giỏ hàng đang trống.');return}if(items.some(i=>i.quantity<1||i.quantity>i.stock)){toast('Số lượng vượt tồn kho. Vui lòng kiểm tra lại giỏ hàng.');return}if(coupon&&discountFor(coupon,subtotal()).error){toast('Mã giảm giá không còn hợp lệ. Vui lòng kiểm tra lại.');coupon='';return}const discount=coupon?discountFor(coupon,subtotal()).amount:0,id='CP'+Date.now().toString().slice(-10),o={id,customer:values.name,email:db.session.email,shippingEmail:values.email,phone:values.phone,address:values.address,note:values.note,payment:values.payment,paid:false,date:new Date().toISOString().slice(0,10),status:'Chờ xử lý',items:items.map(p=>({id:p.id,name:p.name,image:p.image,price:p.price,quantity:p.quantity})),total:subtotal()-discount,discount};db.orders.unshift(o);items.forEach(p=>product(p.id).stock-=p.quantity);db.cart=[];coupon='';save();go('/hoan-tat/'+id);break}case'order-status-form':{const o=db.orders.find(o=>o.id===form.dataset.id);if(updateOrderStatus(o,values.status,values.paid==='on')){render();toast('Đã cập nhật đơn hàng.')}break}case'report-form':if(values.from>values.to){toast('Ngày bắt đầu phải trước ngày kết thúc.');return}reportFrom=values.from;reportTo=values.to;render();break;case'entity-form':{const type=form.dataset.type,id=form.dataset.id,x=id==='new'?{id:Date.now()}:db[type].find(x=>x.id===Number(id)),error=document.querySelector('#entity-error');if(type==='products'){if(+values.price<=0){error.textContent='Giá bán phải lớn hơn 0.';return}if(!Number.isInteger(+values.stock)){error.textContent='Tồn kho phải là số nguyên.';return}values.price=+values.price;values.oldPrice=+values.oldPrice;values.stock=+values.stock;values.active=values.active==='on';values.tag=x.tag||'MỚI'}else if(type==='coupons'){values.code=values.code.toUpperCase();if(db.coupons.some(c=>c.code===values.code&&c.id!==x.id)){error.textContent='Mã giảm giá đã tồn tại.';return}['value','min','max'].forEach(k=>values[k]=+values[k]);if(values.type==='percent'&&values.value>100){error.textContent='Mức giảm phần trăm không được vượt 100.';return}values.active=values.active==='on'}else if(type==='contacts'){values.status='Đã phản hồi'}else if(type==='news'){values.published=values.published==='on'}else if(type==='categories'||type==='suppliers'){values.active=values.active==='on';if(type==='categories'&&db.categories.some(c=>c.name.toLowerCase()===values.name.toLowerCase()&&c.id!==x.id)){error.textContent='Tên danh mục đã tồn tại.';return}if(type==='categories'&&x.name)db.products.filter(p=>p.category===x.name).forEach(p=>p.category=values.name)}Object.assign(x,values);if(id==='new')db[type].push(x);if(type==='customers'&&db.session?.id===x.id)db.session={...x};save();modal.close();render();toast('Đã lưu thay đổi.');break}}});
window.addEventListener('hashchange',handleRoute);
hydrate();
